--
-- Table structure for table `itinerary_days`
--

DROP TABLE IF EXISTS `itinerary_days`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `itinerary_days` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `result_id` bigint unsigned NOT NULL,
  `day_number` int NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `overnight_waypoint_id` bigint unsigned DEFAULT NULL,
  `distance_km` decimal(8,2) DEFAULT NULL,
  `estimated_time_hours` decimal(5,1) DEFAULT NULL,
  `altitude_m` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `itinerary_days_result_id_day_number_unique` (`result_id`,`day_number`),
  KEY `itinerary_days_overnight_waypoint_id_foreign` (`overnight_waypoint_id`),
  CONSTRAINT `itinerary_days_overnight_waypoint_id_foreign` FOREIGN KEY (`overnight_waypoint_id`) REFERENCES `waypoints` (`id`) ON DELETE SET NULL,
  CONSTRAINT `itinerary_days_result_id_foreign` FOREIGN KEY (`result_id`) REFERENCES `planner_results` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3779 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

