  `model_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prompt_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `route_snapshot` json DEFAULT NULL,
  `validation_status` enum('pending','valid','invalid','fallback') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `fallback_used` tinyint(1) NOT NULL DEFAULT '0',
  `validation_errors` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `planner_results_request_id_index` (`request_id`),
  KEY `planner_results_validation_status_index` (`validation_status`),
  CONSTRAINT `planner_results_request_id_foreign` FOREIGN KEY (`request_id`) REFERENCES `planner_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=393 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
