--
-- Table structure for table `route_segments`
--

DROP TABLE IF EXISTS `route_segments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `route_segments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `route_id` bigint unsigned NOT NULL,
  `from_waypoint_id` bigint unsigned NOT NULL,
  `to_waypoint_id` bigint unsigned NOT NULL,
  `sequence` int unsigned NOT NULL,
  `distance_km` decimal(8,2) NOT NULL,
  `estimated_time_hours` decimal(5,1) DEFAULT NULL,
  `elevation_gain_m` int DEFAULT NULL,
  `elevation_loss_m` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `route_segments_active_unique` (`route_id`,`sequence`,(coalesce(`deleted_at`,_utf8mb4'1970-01-01 00:00:00'))),
  KEY `route_segments_from_waypoint_id_foreign` (`from_waypoint_id`),
  KEY `route_segments_to_waypoint_id_foreign` (`to_waypoint_id`),
  KEY `route_segments_route_id_sequence_index` (`route_id`,`sequence`),
  CONSTRAINT `route_segments_from_waypoint_id_foreign` FOREIGN KEY (`from_waypoint_id`) REFERENCES `waypoints` (`id`) ON DELETE CASCADE,
  CONSTRAINT `route_segments_route_id_foreign` FOREIGN KEY (`route_id`) REFERENCES `routes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `route_segments_to_waypoint_id_foreign` FOREIGN KEY (`to_waypoint_id`) REFERENCES `waypoints` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=864 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

