INSERT INTO `travel_safety_incidents` VALUES (4,'Nepal Turns to Mass Burials as Thousands Remain Missing from Floods','nepal-turns-to-mass-burials-as-thousands-remain-missing-from-floods-6a954f9c2031c','flood','Only a fraction of the over 4,200 missing in Nepal are turning up among the dead, underscoring a bleak reality: The death toll is likely to keep rising for days to come.','moderate','detected',NULL,NULL,'',NULL,NULL,NULL,NULL,'2026-08-31 04:10:40','2026-08-31 04:10:40',NULL,0.6,0,'severe',NULL,'{\"url\": \"https://www.nytimes.com/2026/08/30/world/asia/nepal-floods-mass-burials-missing.html\", \"source_id\": 4}','2026-08-31 04:10:40','2026-08-31 04:10:40',NULL),(5,'This Governor Could Lose His Primary. A Bridge May Be to Blame.','this-governor-could-lose-his-primary-a-bridge-may-be-to-blame-6a954f9c2768d','other','The closure of a crucial Rhode Island bridge for safety reasons in 2023, and the traffic nightmare that followed, have dogged Gov. Dan McKee in the Democratic primary.','moderate','detected',NULL,NULL,'',NULL,NULL,NULL,NULL,'2026-08-31 04:10:40','2026-08-31 04:10:40',NULL,0.6,0,'moderate',NULL,'{\"url\": \"https://www.nytimes.com/2026/08/30/us/dan-mckee-rhode-island-bridge.html\", \"source_id\": 4}','2026-08-31 04:10:40','2026-08-31 04:10:40',NULL),(6,'Test Incident in Pokhara','test-pokhara-6a95546e1a43f','flood',NULL,'high','verified',28.20953800,83.99140200,'Pokhara',NULL,NULL,NULL,NULL,'2026-08-31 04:31:14',NULL,NULL,0.4,0,NULL,NULL,NULL,'2026-08-31 04:31:14','2026-08-31 04:48:57',NULL),(7,'Test Phase 4 - Pokhara Flood','test-phase4-pokhara','flood',NULL,'high','active',28.20953800,83.99140200,'Pokhara',NULL,NULL,NULL,NULL,'2026-08-31 05:03:56',NULL,NULL,0.7,0,NULL,NULL,NULL,'2026-08-31 05:03:56','2026-08-31 05:19:44',NULL),(8,'Severe Flooding in Rasuwa Gadhi - Hundreds Missing','rasuwa-flood-6a96421a922de','flood','Heavy rainfall caused massive flooding and landslides in Rasuwa Gadhi and surrounding areas. Hundreds of travelers missing, roads blocked.','critical','active',28.07000000,85.37000000,'Rasuwa Gadhi','Rasuwa','Bagmati',50000,NULL,'2026-08-31 21:25:18','2026-08-31 21:25:18',NULL,0.9,1,'severe',NULL,NULL,'2026-08-31 21:25:18','2026-08-31 21:25:18',NULL);
